<script setup lang="ts">
import { Check, Pencil, Trash2, LockKeyhole } from '@lucide/vue';
import type { Task } from '../../types';
import BaseBadge from '../atoms/BaseBadge.vue';
defineProps<{ task: Task; busy?: boolean }>();
defineEmits<{ edit: [task: Task]; complete: [task: Task]; remove: [task: Task] }>();
const date = (value: string) => new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value));
</script>
<template><article class="task-card"><div class="task-main"><div class="task-title-row"><h3>{{ task.title }}</h3><BaseBadge :status="task.status"/></div><p v-if="task.description" class="muted desc">{{ task.description }}</p><div class="meta"><span>{{ task.owner.name }}</span><span aria-hidden="true">·</span><time :datetime="task.createdAt">{{ date(task.createdAt) }}</time></div></div><div class="task-actions"><template v-if="task.status === 'PENDING'"><button class="btn btn-ghost icon-btn" title="Editar tarefa" aria-label="Editar tarefa" :disabled="busy" @click="$emit('edit', task)"><Pencil :size="17"/></button><button class="btn btn-ghost icon-btn complete-action" title="Concluir tarefa" aria-label="Concluir tarefa" :disabled="busy" @click="$emit('complete', task)"><Check :size="18"/></button><button class="btn btn-ghost icon-btn delete-action" title="Excluir tarefa" aria-label="Excluir tarefa" :disabled="busy" @click="$emit('remove', task)"><Trash2 :size="17"/></button></template><span v-else class="locked" title="Tarefas concluídas não podem ser excluídas"><LockKeyhole :size="15"/> Protegida</span></div></article></template>
<style scoped>.task-card{display:flex;justify-content:space-between;gap:18px;padding:21px 24px;border-bottom:1px solid var(--border);transition:background var(--ease)}.task-card:last-child{border-bottom:0}.task-card:hover{background:var(--surface-muted)}.task-main{min-width:0;flex:1}.task-title-row{display:flex;align-items:center;flex-wrap:wrap;gap:9px}.task-title-row h3{font-size:16px;letter-spacing:-.015em;margin:0}.desc{font-size:13px;margin:9px 0 12px;white-space:pre-wrap;overflow-wrap:anywhere}.meta{display:flex;gap:9px;color:var(--text-muted);font-size:12px;margin-top:12px}.task-actions{display:flex;align-items:center;gap:3px}.complete-action{color:var(--success)}.delete-action{color:var(--danger)}.locked{display:flex;align-items:center;gap:5px;color:var(--text-muted);font-size:12px;white-space:nowrap}@media(max-width:600px){.task-card{padding:17px;flex-direction:column;gap:6px}.task-actions{justify-content:flex-end}.task-actions .btn{min-width:42px;min-height:42px}}</style>
